@media(max-width:1200px) {
.ad_unit_height55{height:250px}
}
@media(max-width:768px) {
.ad_unit_height55{height:250px}
}

  window.googletag = window.googletag || {cmd: []};
  googletag.cmd.push(function() {
    googletag.defineSlot('/21918299361/Leb24_300x250_InsideArticle_Zoning', [300, 250], 'div-gpt-ad-1618312246857-0').setTargeting('Leb24_Category', ['~content_type~']).addService(googletag.pubads());
    googletag.pubads().enableSingleRequest();
    googletag.pubads().collapseEmptyDivs();
    googletag.enableServices();
  });


    googletag.cmd.push(function() { googletag.display('div-gpt-ad-1618312246857-0'); });




وقالت الجزائر إن "قتل الجيش المغربي لمواطنين جزائريين لن يمر دون عقاب".
وذكرت وكالة الأنباء الجزائرية الرسمية أن الرئاسة وصفت العمل بأنه "جبان".
ونفى الجيش الموريتاني، من جانبه، وقوع هجوم داخل الأراضي الموريتانية، وقال في بيان: "من أجل إنارة الرأي العام وتصحيح المعلومات المتداولة، تنفي مديرية الاتصال والعلاقات العامة بقيادة الأركان العامة للجيوش حدوث أي هجوم داخل التراب الوطني".
وجاء الإعلان الجزائري بعد أيام من قرارها وقف ضخ الغاز الجزائري إلى المغرب بسبب "الممارسات ذات الطابع العدواني، من المملكة المغربية تجاه الجزائر، التي تمس بالوحدة الوطنية".

وكانت الجزائر قطعت علاقاتها الدبلوماسية مع المغرب، في أغسطس، واتهمته بارتكاب "أعمال عدائية"، وهو ما نفته الرباط.
وأعرب المغرب وقتها في بيان عن وزارة الخارجية عن "أسفه للقرار (قطع العلاقات)"، ووصفه بـ"غير المبرّر تماما"، مؤكدا أنه "يرفض بشكل قاطع المبررات الزائفة، بل العبثية التي انبنى عليها".
وتعد الصحراء الغربية السبب الرئيسي للخلاف بين البلدين الجارين، وهي موضوع نزاع منذ عقود بين المغرب وجبهة البوليساريو المدعومة من الجزائر، وهي منطقة تصنفها الأمم المتحدة بين "الأقاليم غير المتمتعة بالحكم الذاتي".
